import { useState } from 'react';
import { JxButton, JxModal } from '@jinx-ui/react';

interface DeleteProjectProps {
  onConfirm: () => void;
  projectName?: string;
}

export default function DeleteProject({ onConfirm, projectName }: DeleteProjectProps) {
  const [confirmOpen, setConfirmOpen] = useState(false);

  const confirm = () => {
    setConfirmOpen(false);
    onConfirm();
  };

  return (
    <>
      <JxButton variant="danger" onClick={() => setConfirmOpen(true)}>
        Удалить проект
      </JxButton>
      <JxModal
        open={confirmOpen}
        onOpenChange={setConfirmOpen}
        intent="danger"
        title="Удалить проект?"
        message={
          projectName
            ? `Проект «${projectName}» и все его данные будут удалены безвозвратно. Действие необратимо.`
            : 'Проект и все его данные будут удалены безвозвратно. Действие необратимо.'
        }
      >
        <JxButton variant="ghost" onClick={() => setConfirmOpen(false)}>
          Отмена
        </JxButton>
        <JxButton variant="danger" onClick={confirm}>
          Удалить
        </JxButton>
      </JxModal>
    </>
  );
}

